CREATE PROCEDURE InsertOrUpdateAccount
    @account_id INT,
    @district_id INT,
    @frequency VARCHAR(50),
    @date DATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM account WHERE account_id = @account_id)
    BEGIN
        UPDATE account
        SET frequency = @frequency, date = @date
        WHERE account_id = @account_id;
    END
    ELSE
    BEGIN
        INSERT INTO account (account_id, district_id, frequency, date)
        VALUES (@account_id, @district_id, @frequency, @date);
    END;
END;

