(
    @CatID INT,
    @isBusinessCat BIT
)
RETURNS BIT
AS
BEGIN
    IF @isBusinessCat = 1
    BEGIN
        RETURN 1;
    END;

    IF EXISTS (SELECT 1 FROM BusinessCategories WHERE ID = @CatID)
    BEGIN
        RETURN 0;
    END;
    RETURN 1;
END;

